fn ast_contains_external_context(node: &ASTNode, provider: &dyn FunctionProvider) -> bool {
    match &node.node_type {
        ASTNodeType::Function { name, args } => {
            let canonical = name.rsplit('.').next().unwrap_or(name);
            let known_function = provider
                .get_function_for_planning("", name)
                .or_else(|| provider.get_function_for_planning("", canonical));
            let global_function = crate::function_registry::get_for_planning("", name)
                .or_else(|| crate::function_registry::get_for_planning("", canonical));
            if matches!(
                canonical.to_ascii_uppercase().as_str(),
                "CELL" | "INFO" | "WEBSERVICE" | "RTD" | "CUBEMEMBER" | "CUBEVALUE"
            ) || (known_function.is_none() && !name.to_ascii_uppercase().starts_with("_XLFN."))
                || (global_function.is_none() && !name.to_ascii_uppercase().starts_with("_XLFN."))
            {
                return true;
            }
            args.iter()
                .any(|arg| ast_contains_external_context(arg, provider))
        }
        ASTNodeType::Call { callee, args } => {
            ast_contains_external_context(callee, provider)
                || args
                    .iter()
                    .any(|arg| ast_contains_external_context(arg, provider))
        }
        ASTNodeType::UnaryOp { expr, .. } => ast_contains_external_context(expr, provider),
        ASTNodeType::BinaryOp { left, right, .. } => {
            ast_contains_external_context(left, provider)
                || ast_contains_external_context(right, provider)
        }
        ASTNodeType::Array(rows) => rows
            .iter()
            .flatten()
            .any(|item| ast_contains_external_context(item, provider)),
        ASTNodeType::Reference { .. } | ASTNodeType::Literal(_) | ASTNodeType::Omitted => false,
    }
}

fn literal_shape(value: &LiteralValue) -> (usize, usize) {
    match value {
        LiteralValue::Array(rows) => (rows.len(), rows.iter().map(Vec::len).max().unwrap_or(0)),
        _ => (1, 1),
    }
}

fn fingerprint_collected_edges(n: usize, edges: &FxHashSet<(u32, u32)>) -> u64 {
    let mut edges = edges.iter().copied().collect::<Vec<_>>();
    edges.sort_unstable();
    edges.dedup();
    edges
        .iter()
        .fold(0xcbf29ce484222325_u64 ^ n as u64, |hash, &(from, to)| {
            (hash ^ from as u64)
                .wrapping_mul(0x100000001b3)
                .wrapping_add(to as u64)
                .wrapping_mul(0x100000001b3)
        })
}

fn fingerprint_live_edges_for_sources(
    n: usize,
    out_edges: &[Vec<u32>],
    excluded: &[bool],
    sources: &[bool],
) -> u64 {
    let mut edges = Vec::new();
    for (from, targets) in out_edges.iter().enumerate() {
        if excluded.get(from).copied().unwrap_or(true)
            || !sources.get(from).copied().unwrap_or(false)
        {
            continue;
        }
        for &to in targets {
            edges.push((from as u32, to));
        }
    }
    edges.sort_unstable();
    edges.dedup();
    edges
        .iter()
        .fold(0xcbf29ce484222325_u64 ^ n as u64, |hash, &(from, to)| {
            (hash ^ from as u64)
                .wrapping_mul(0x100000001b3)
                .wrapping_add(to as u64)
                .wrapping_mul(0x100000001b3)
        })
}

fn fingerprint_origin_maps(
    n: usize,
    origins: &[FxHashMap<u32, u16>],
    sources: &[bool],
    excluded: &[bool],
) -> u64 {
    let mut entries = Vec::new();
    for (from, row) in origins.iter().enumerate() {
        if excluded.get(from).copied().unwrap_or(true)
            || !sources.get(from).copied().unwrap_or(false)
        {
            continue;
        }
        for (&to, &mask) in row {
            entries.push((from as u32, to, mask));
        }
    }
    entries.sort_unstable();
    entries.dedup();
    entries.iter().fold(
        0xcbf29ce484222325_u64 ^ n as u64,
        |hash, &(from, to, mask)| {
            (hash ^ from as u64)
                .wrapping_mul(0x100000001b3)
                .wrapping_add(to as u64)
                .wrapping_mul(0x100000001b3)
                .wrapping_add(mask as u64)
                .wrapping_mul(0x100000001b3)
        },
    )
}

fn fingerprint_live_edges(n: usize, out_edges: &[Vec<u32>], excluded: &[bool]) -> u64 {
    let mut edges = Vec::new();
    for (from, targets) in out_edges.iter().enumerate() {
        if excluded.get(from).copied().unwrap_or(true) {
            continue;
        }
        for &to in targets {
            edges.push((from as u32, to));
        }
    }
    edges.sort_unstable();
    edges.dedup();
    edges
        .iter()
        .fold(0xcbf29ce484222325_u64 ^ n as u64, |hash, &(from, to)| {
            (hash ^ from as u64)
                .wrapping_mul(0x100000001b3)
                .wrapping_add(to as u64)
                .wrapping_mul(0x100000001b3)
        })
}

#[derive(Debug, Clone, Copy)]
struct SccPartitionSummary {
    frontier_member_count: usize,
    static_member_count: usize,
    static_live_edge_count: usize,
    frontier_boundary_edge_count: usize,
    static_cycle_count: usize,
    static_cycle_member_count: usize,
}

fn summarize_scc_partition(
    n: usize,
    out_edges: &[Vec<u32>],
    excluded: &[bool],
    volatile: &[bool],
    dynamic: &[bool],
) -> SccPartitionSummary {
    let mut static_indices = vec![usize::MAX; n];
    let mut static_member_count = 0;
    for index in 0..n {
        if !excluded[index] && !volatile[index] && !dynamic[index] {
            static_indices[index] = static_member_count;
            static_member_count += 1;
        }
    }
    let frontier_member_count = n.saturating_sub(static_member_count);
    let mut static_edges = Vec::new();
    let mut frontier_boundary_edge_count = 0;
    for (from, targets) in out_edges.iter().enumerate() {
        if excluded.get(from).copied().unwrap_or(true) {
            continue;
        }
        for &to in targets {
            let to = to as usize;
            if to >= n || excluded[to] {
                continue;
            }
            match (static_indices[from], static_indices[to]) {
                (from_static, to_static)
                    if from_static != usize::MAX && to_static != usize::MAX =>
                {
                    static_edges.push((from_static as u32, to_static as u32));
                }
                _ => frontier_boundary_edge_count += 1,
            }
        }
    }
    static_edges.sort_unstable();
    static_edges.dedup();
    let static_analysis =
        (static_member_count > 0).then(|| analyze_live_graph(static_member_count, &static_edges));
    let static_cycle_count = static_analysis
        .as_ref()
        .map_or(0, |analysis| analysis.cycle_count);
    let static_cycle_member_count = static_analysis.as_ref().map_or(0, |analysis| {
        analysis
            .in_cycle
            .iter()
            .filter(|in_cycle| **in_cycle)
            .count()
    });
    SccPartitionSummary {
        frontier_member_count,
        static_member_count,
        static_live_edge_count: static_edges.len(),
        frontier_boundary_edge_count,
        static_cycle_count,
        static_cycle_member_count,
    }
}

fn summarize_edge_origins(
    origins: Option<&[FxHashMap<u32, u16>]>,
    dynamic_members: &[bool],
    volatile_members: &[bool],
    excluded: &[bool],
    static_only: bool,
) -> Vec<(String, usize)> {
    let Some(origins) = origins else {
        return Vec::new();
    };
    let all_origins = [
        LiveEdgeOrigin::DirectCell,
        LiveEdgeOrigin::Range,
        LiveEdgeOrigin::WholeRow,
        LiveEdgeOrigin::WholeColumn,
        LiveEdgeOrigin::NamedRange,
        LiveEdgeOrigin::Table,
        LiveEdgeOrigin::DynamicReference,
        LiveEdgeOrigin::Other,
    ];
    let mut counts = FxHashMap::<&'static str, usize>::default();
    for (from, row) in origins.iter().enumerate() {
        if static_only
            && (excluded.get(from).copied().unwrap_or(true)
                || dynamic_members.get(from).copied().unwrap_or(false)
                || volatile_members.get(from).copied().unwrap_or(false))
        {
            continue;
        }
        for (&to, &mask) in row {
            let to = to as usize;
            if static_only
                && (excluded.get(to).copied().unwrap_or(true)
                    || dynamic_members.get(to).copied().unwrap_or(false)
                    || volatile_members.get(to).copied().unwrap_or(false))
            {
                continue;
            }
            let mut effective_mask = mask;
            if dynamic_members.get(from).copied().unwrap_or(false) {
                effective_mask |= LiveEdgeOrigin::DynamicReference.bit();
            }
            for origin in all_origins {
                if effective_mask & origin.bit() != 0 {
                    *counts.entry(origin.label()).or_default() += 1;
                }
            }
        }
    }
    let mut result: Vec<_> = counts
        .into_iter()
        .map(|(origin, count)| (origin.to_string(), count))
        .collect();
    result.sort_unstable();
    result
}

