    pub fn formula_value_fingerprint(&self) -> (usize, u64) {
        use std::hash::{Hash, Hasher};
        let mut vertices = self.graph.get_evaluation_vertices();
        vertices.sort_unstable_by_key(|vertex| vertex.0);
        let mut hasher = std::collections::hash_map::DefaultHasher::new();
        let mut count = 0;
        for vertex in vertices {
            vertex.0.hash(&mut hasher);
            let value = self
                .graph
                .get_cell_ref(vertex)
                .and_then(|cell| {
                    self.get_cell_value(
                        self.graph.sheet_name(cell.sheet_id),
                        cell.coord.row() + 1,
                        cell.coord.col() + 1,
                    )
                })
                .or_else(|| self.graph.get_value(vertex));
            if let Some(value) = value {
                count += 1;
                format!("{value:?}").hash(&mut hasher);
            } else {
                0_u8.hash(&mut hasher);
            }
        }
        (count, hasher.finish())
    }

    pub fn formula_output_snapshot(&self) -> Vec<(String, LiteralValue)> {
        let mut output = self
            .graph
            .vertices_with_formulas()
            .filter_map(|vertex| {
                let address = self
                    .graph
                    .get_cell_ref(vertex)
                    .map(|cell| {
                        format!(
                            "{}!{}{}",
                            self.graph.sheet_name(cell.sheet_id),
                            Self::col_to_letters(cell.coord.col() + 1),
                            cell.coord.row() + 1,
                        )
                    })
                    .or_else(|| self.graph.name_key_for_vertex(vertex))?;
                let value = self
                    .graph
                    .get_cell_ref(vertex)
                    .and_then(|cell| {
                        self.get_cell_value(
                            self.graph.sheet_name(cell.sheet_id),
                            cell.coord.row() + 1,
                            cell.coord.col() + 1,
                        )
                    })
                    .or_else(|| self.graph.get_value(vertex))
                    .unwrap_or(LiteralValue::Empty);
                Some((address, value))
            })
            .collect::<Vec<_>>();
        output.sort_unstable_by(|left, right| left.0.cmp(&right.0));
        output
    }

