    pub fn sheet_id(&self, name: &str) -> Option<SheetId> {
        self.graph.sheet_id(name)
    }

    pub fn sheet_id_mut(&mut self, name: &str) -> SheetId {
        self.add_sheet(name)
            .unwrap_or_else(|_| self.graph.sheet_id_mut(name))
    }

    pub fn sheet_name(&self, id: SheetId) -> &str {
        self.graph.sheet_name(id)
    }

    pub fn add_sheet(&mut self, name: &str) -> Result<SheetId, ExcelError> {
        let id = self.graph.add_sheet(name)?;
        self.ensure_arrow_sheet(name);
        // Adding a sheet does not change any existing span result or dependency.
        self.mark_topology_edited();
        Ok(id)
    }

    pub fn duplicate_sheet(&mut self, source: &str, new_name: &str) -> Result<SheetId, ExcelError> {
        let source_id = self.graph.sheet_id(source).ok_or_else(|| {
            ExcelError::new(ExcelErrorKind::Value).with_message("Source sheet does not exist")
        })?;
        if new_name.is_empty() || new_name.len() > 255 {
            return Err(ExcelError::new(ExcelErrorKind::Value).with_message("Invalid sheet name"));
        }
        if self.graph.sheet_id(new_name).is_some() {
            return Err(ExcelError::new(ExcelErrorKind::Value)
                .with_message(format!("Sheet '{new_name}' already exists")));
        }
        // Materialize only spans on the source sheet so graph duplication sees
        // the formulas being copied. Spans on unrelated sheets remain active.
        self.demote_spans_preserving_computed_overlays(source_id, Region::whole_sheet(source_id))
            .map_err(Self::editor_error_to_excel)?;
        let new_id = self.graph.duplicate_sheet(source_id, new_name)?;

        if let Some(source_sheet) = self.arrow_sheets.sheet(source).cloned() {
            let mut copied_sheet = source_sheet;
            copied_sheet.name = Arc::<str>::from(new_name);
            self.arrow_sheets.sheets.push(copied_sheet);
        } else {
            self.ensure_arrow_sheet(new_name);
        }

        let duplicated_formulas = self
            .graph
            .formula_vertices()
            .into_iter()
            .filter(|vertex| {
                self.graph
                    .get_cell_ref(*vertex)
                    .is_some_and(|cell| cell.sheet_id == new_id)
            })
            .collect::<Vec<_>>();
        self.graph.mark_vertices_dirty_batch(&duplicated_formulas);
        self.mark_topology_edited();
        Ok(new_id)
    }

    fn ensure_arrow_sheet(&mut self, name: &str) {
        if self.arrow_sheets.sheet(name).is_some() {
            return;
        }
        self.arrow_sheets
            .sheets
            .push(crate::arrow_store::ArrowSheet {
                name: std::sync::Arc::<str>::from(name),
                date_system: self.config.date_system,
                columns: Vec::new(),
                nrows: 0,
                chunk_starts: Vec::new(),
                chunk_rows: 32 * 1024,
            });
    }

    pub fn remove_sheet(&mut self, sheet_id: SheetId) -> Result<(), ExcelError> {
        let name = self.graph.sheet_name(sheet_id).to_string();
        // Removing a sheet only affects spans on that sheet and spans reading
        // from that sheet. Preserve spans on unrelated sheets so sheet
        // lifecycle operations do not collapse the whole FormulaPlane.
        self.demote_spans_preserving_computed_overlays(sheet_id, Region::whole_sheet(sheet_id))
            .map_err(Self::editor_error_to_excel)?;
        self.purge_derived_formats_for_sheet(sheet_id);
        self.graph.remove_sheet(sheet_id)?;
        self.arrow_sheets.sheets.retain(|s| s.name.as_ref() != name);
        // Sheet removal can change cross-sheet refs, names, and default-sheet
        // resolution. Until those domains have a complete exact dependency
        // proof, retain the documented graph-owned global invalidation.
        self.clear_all_computed_overlays();
        self.mark_all_formula_vertices_dirty();
        self.clear_staged_formulas_for_sheet(&name);
        if self.row_visibility.remove(&sheet_id).is_some() {
            self.invalidate_row_visibility_mask_cache();
        }
        self.record_formula_plane_structural_change(StructuralScope::RemovedSheet(sheet_id));
        self.mark_topology_edited();
        Ok(())
    }

    /// Helper to synchronize the Arrow-backed storage layer.
    fn rename_sheet_in_arrow_store(&mut self, target_name: &str, new_name: &str) -> bool {
        if let Some(asheet) = self
            .arrow_sheets
            .sheets
            .iter_mut()
            .find(|s| s.name.as_ref() == target_name)
        {
            asheet.name = std::sync::Arc::<str>::from(new_name);
            return true;
        }
        false
    }

    pub fn rename_sheet(&mut self, sheet_id: SheetId, new_name: &str) -> Result<(), ExcelError> {
        let old_name = self.graph.sheet_name(sheet_id).to_string();

        // Speculative Storage Update
        // Update name in storage FIRST so the Evaluator can find it during Graph rescue.
        self.rename_sheet_in_arrow_store(&old_name, new_name);

        // Graph Update (Metadata + Rescue Logic)
        match self.graph.rename_sheet(sheet_id, new_name) {
            Ok(_) => {
                self.rename_staged_formula_sheet(&old_name, new_name);
                // Success! Invalidate cache for the moved sheet
                let sheet_vertices: Vec<VertexId> = self
                    .graph
                    .grid_vertices_in_sheet(sheet_id)
                    .map(|(id, _)| id)
                    .collect();
                for v_id in sheet_vertices {
                    self.graph.mark_vertex_dirty(v_id);
                }
                // Sheet rename preserves SheetId and therefore formula dependencies.
                self.mark_topology_edited();
                Ok(())
            }
            Err(e) => {
                // ROLLBACK: Revert storage if graph rejected the name
                self.rename_sheet_in_arrow_store(new_name, &old_name);
                Err(e)
            }
        }
    }

    pub fn named_ranges_iter(
        &self,
    ) -> impl Iterator<Item = (&String, &crate::engine::named_range::NamedRange)> {
        self.graph.named_ranges_iter()
    }

    pub fn sheet_named_ranges_iter(
        &self,
    ) -> impl Iterator<Item = (&(SheetId, String), &crate::engine::named_range::NamedRange)> {
        self.graph.sheet_named_ranges_iter()
    }

    pub fn resolve_name_entry(
        &self,
        name: &str,
        current_sheet: SheetId,
    ) -> Option<&crate::engine::named_range::NamedRange> {
        self.graph.resolve_name_entry(name, current_sheet)
    }

    /// The [`NameScope`] an optional scope-sheet argument denotes.
    ///
    /// `None` means **workbook scope**, not "the default sheet": a caller that
    /// supplies no sheet context is asking about workbook-scoped names only.
    /// An unknown sheet name is a malformed query and errors rather than
    /// silently degrading to another sheet's scope (issue #110).
    ///
    /// This is the one owned derivation from `Option<&str>` to a name scope;
    /// every scope-taking entry point routes through it.
    pub(crate) fn name_query_scope(
        &self,
        scope_sheet: Option<&str>,
    ) -> Result<NameScope, ExcelError> {
        match scope_sheet {
            None => Ok(NameScope::Workbook),
            Some(sheet) => self
                .graph
                .sheet_id(sheet)
                .map(NameScope::Sheet)
                .ok_or_else(|| {
                    ExcelError::new(ExcelErrorKind::Ref)
                        .with_message(format!("name scope sheet not found: {sheet}"))
                }),
        }
    }

    /// Whether `name` resolves in the scope denoted by `scope_sheet`.
    ///
    /// `scope_sheet == None` asks about workbook scope only; a name scoped to a
    /// single sheet (including the default sheet) does not answer it. An unknown
    /// sheet name resolves nothing.
    /// Resolve a [`SharedSheetLocator`](crate::reference::SharedSheetLocator)
    /// against an explicit context sheet.
    ///
    /// Thin forwarder to
    /// [`SheetRegistry::resolve_locator`](crate::engine::sheet_registry::SheetRegistry::resolve_locator),
    /// the single owned derivation. `Current` resolves to `context_sheet`, never
    /// to the workbook's default sheet.
    fn resolve_sheet_locator(
        &self,
        locator: &crate::reference::SharedSheetLocator<'_>,
        context_sheet: SheetId,
    ) -> Result<SheetId, ExcelError> {
        self.graph
            .sheet_reg()
            .resolve_locator(locator, context_sheet)
    }

    pub fn has_name(&self, name: &str, scope_sheet: Option<&str>) -> bool {
        let Ok(scope) = self.name_query_scope(scope_sheet) else {
            return false;
        };
        self.graph
            .resolve_name_entry_in_scope(name, scope)
            .is_some()
    }

    /// The current value of `name` in the scope denoted by `scope_sheet`.
    ///
    /// Scoping follows [`Self::has_name`]: `None` is workbook scope only.
    pub fn resolved_name_value(
        &self,
        name: &str,
        scope_sheet: Option<&str>,
    ) -> Option<LiteralValue> {
        let scope = self.name_query_scope(scope_sheet).ok()?;
        let entry = self.graph.resolve_name_entry_in_scope(name, scope)?;
        self.graph.get_value(entry.vertex)
    }

    pub fn table_metadata(&self, name: &str) -> Option<TableMetadata> {
        let entry = self.graph.resolve_table_entry(name)?;
        Some(TableMetadata {
            name: entry.name.clone(),
            sheet: self.graph.sheet_name(entry.sheet_id()).to_string(),
            start_row: entry.range.start.coord.row() + 1,
            start_col: entry.range.start.coord.col() + 1,
            end_row: entry.range.end.coord.row() + 1,
            end_col: entry.range.end.coord.col() + 1,
            header_row: entry.header_row,
            headers: entry.headers.clone(),
            totals_row: entry.totals_row,
        })
    }

    /// Metadata for every defined table, ordered by name.
    pub fn tables(&self) -> Vec<TableMetadata> {
        self.graph
            .table_names()
            .into_iter()
            .filter_map(|name| self.table_metadata(&name))
            .collect()
    }

    pub fn named_ranges_snapshot(&self) -> Vec<crate::engine::named_range::NamedRangeSnapshot> {
        let mut out: Vec<crate::engine::named_range::NamedRangeSnapshot> = Vec::new();

        for (name, named) in self.graph.named_ranges_iter() {
            out.push(crate::engine::named_range::NamedRangeSnapshot {
                name: name.clone(),
                scope: NameScope::Workbook,
                definition: named.definition.clone(),
            });
        }

        for ((sheet_id, name), named) in self.graph.sheet_named_ranges_iter() {
            out.push(crate::engine::named_range::NamedRangeSnapshot {
                name: name.clone(),
                scope: NameScope::Sheet(*sheet_id),
                definition: named.definition.clone(),
            });
        }

        out.sort_by(|a, b| {
            let a_scope = match a.scope {
                NameScope::Workbook => (0u8, 0u32),
                NameScope::Sheet(id) => (1u8, u32::from(id)),
            };
            let b_scope = match b.scope {
                NameScope::Workbook => (0u8, 0u32),
                NameScope::Sheet(id) => (1u8, u32::from(id)),
            };
            a_scope.cmp(&b_scope).then_with(|| a.name.cmp(&b.name))
        });

        out
    }

    pub fn named_ranges_snapshot_for_sheet(
        &self,
        sheet_id: SheetId,
    ) -> Vec<crate::engine::named_range::NamedRangeSnapshot> {
        self.named_ranges_snapshot()
            .into_iter()
            .filter(|entry| match entry.scope {
                NameScope::Workbook => true,
                NameScope::Sheet(id) => id == sheet_id,
            })
            .collect()
    }

    fn is_skippable_load_name_error(error: &ExcelError) -> bool {
        error.kind == ExcelErrorKind::Name
            && error.message.as_deref().is_some_and(|message| {
                message.starts_with("Invalid name:")
                    || message.starts_with("Name collision under normalization:")
                    || message.starts_with("Name collision under normalization in sheet:")
            })
    }

    #[doc(hidden)]
    pub fn define_names_for_load(
        &mut self,
        definitions: Vec<(String, NamedDefinition, NameScope)>,
    ) -> Result<DefinedNameLoadReport, ExcelError> {
        let before = self.graph.name_definition_stats();
        let use_batch = self.graph.formula_authority().active_span_count() == 0;
        let mut report = DefinedNameLoadReport {
            attempted: definitions.len() as u64,
            ..DefinedNameLoadReport::default()
        };
        if use_batch {
            self.graph.begin_symbol_revision_batch();
        }
        let result = (|| {
            for (name, definition, scope) in definitions {
                let result = if use_batch {
                    self.graph.define_name(&name, definition, scope)
                } else {
                    self.define_name(&name, definition, scope)
                };
                match result {
                    Ok(()) => report.accepted = report.accepted.saturating_add(1),
                    Err(error) if Self::is_skippable_load_name_error(&error) => {
                        report.skipped = report.skipped.saturating_add(1);
                    }
                    Err(error) => return Err(error),
                }
            }
            if use_batch {
                let started = Instant::now();
                report.pending_name_resolution_links =
                    self.graph.resolve_pending_name_references_for_load() as u64;
                report.pending_name_resolution_ns = started.elapsed().as_nanos();
            }
            Ok(())
        })();
        if use_batch {
            self.graph.end_symbol_revision_batch();
        }
        if use_batch && report.accepted != 0 {
            self.record_formula_plane_structural_change(StructuralScope::AllSheets);
            self.mark_topology_edited();
        }
        let after = self.graph.name_definition_stats();
        report.formula_dependency_extraction_calls = after
            .formula_dependency_extraction_calls
            .saturating_sub(before.formula_dependency_extraction_calls);
        report.formula_dependency_extraction_ns = after
            .formula_dependency_extraction_ns
            .saturating_sub(before.formula_dependency_extraction_ns);
        report.publication_ns = after.publication_ns.saturating_sub(before.publication_ns);
        report.symbol_vertex_allocations = after
            .symbol_vertex_allocations
            .saturating_sub(before.symbol_vertex_allocations);
        report.name_index_insertions = after
            .name_index_insertions
            .saturating_sub(before.name_index_insertions);
        report.symbol_revision_bumps = after
            .symbol_revision_bumps
            .saturating_sub(before.symbol_revision_bumps);
        report.symbol_revision_updates = after
            .symbol_revision_updates
            .saturating_sub(before.symbol_revision_updates);
        result.map(|()| report)
    }

    pub fn define_name(
        &mut self,
        name: &str,
        definition: NamedDefinition,
        scope: NameScope,
    ) -> Result<(), ExcelError> {
        // A new define can flip resolution for spans that previously resolved
        // the same name through another scope (e.g. a sheet-scoped name
        // shadowing a workbook-scoped one). Demote those spans BEFORE the
        // registry changes so their cells re-ingest and re-resolve through
        // the normal legacy path.
        self.graph.validate_define_name(name, scope)?;
        let has_dependent_spans = !self.exact_name_dependent_span_refs([name]).is_empty();
        if has_dependent_spans && matches!(definition, NamedDefinition::Formula { .. }) {
            return Err(ExcelError::new(ExcelErrorKind::NImpl).with_message(
                "formula-name shadowing with active FormulaPlane dependents is not supported",
            ));
        }
        let prepared = self
            .prepare_name_dependent_span_demotion([name])
            .map_err(Self::editor_error_to_excel)?;
        let demoted = self
            .commit_name_dependent_span_demotion(prepared)
            .map_err(Self::editor_error_to_excel)?;
        self.graph.define_name(name, definition, scope)?;
        self.record_formula_plane_structural_change(StructuralScope::AllSheets);
        if !demoted {
            self.mark_topology_edited();
        }
        Ok(())
    }

    pub fn update_name(
        &mut self,
        name: &str,
        definition: NamedDefinition,
        scope: NameScope,
    ) -> Result<(), ExcelError> {
        // Demote name-dependent spans BEFORE the registry update: the demoted
        // cells re-materialize as legacy vertices attached to the name vertex
        // (via their resolved-name dep plans), so the registry update's
        // dependent dirtying reaches them exactly like long-lived legacy
        // formulas.
        self.graph.validate_existing_name(name, scope)?;
        let prepared = self
            .prepare_name_dependent_span_demotion([name])
            .map_err(Self::editor_error_to_excel)?;
        let demoted = self
            .commit_name_dependent_span_demotion(prepared)
            .map_err(Self::editor_error_to_excel)?;
        self.graph.update_name(name, definition, scope)?;
        self.record_formula_plane_structural_change(StructuralScope::AllSheets);
        if !demoted {
            self.mark_topology_edited();
        }
        Ok(())
    }

    pub fn delete_name(&mut self, name: &str, scope: NameScope) -> Result<(), ExcelError> {
        // Demote first (see update_name): the demoted legacy vertices become
        // dependents of the name vertex, so delete_name dirties them and they
        // re-evaluate to #NAME? exactly as legacy formulas do.
        self.graph.validate_existing_name(name, scope)?;
        let prepared = self
            .prepare_name_dependent_span_demotion([name])
            .map_err(Self::editor_error_to_excel)?;
        let demoted = self
            .commit_name_dependent_span_demotion(prepared)
            .map_err(Self::editor_error_to_excel)?;
        self.graph.delete_name(name, scope)?;
        self.record_formula_plane_structural_change(StructuralScope::AllSheets);
        if !demoted {
            self.mark_topology_edited();
        }
        Ok(())
    }

    fn exact_name_dependent_span_refs<'a>(
        &self,
        names: impl IntoIterator<Item = &'a str>,
    ) -> Vec<FormulaSpanRef> {
        let authority = self.graph.formula_authority();
        let mut refs = names
            .into_iter()
            .flat_map(|name| authority.plane.name_dependent_span_refs(name))
            .collect::<Vec<_>>();
        refs.sort_unstable_by_key(|span_ref| {
            (span_ref.id.0, span_ref.generation, span_ref.version)
        });
        refs.dedup();
        refs
    }

    fn name_event_names(events: &[ChangeEvent]) -> Vec<String> {
        events
            .iter()
            .filter_map(|event| match event {
                ChangeEvent::DefineName { name, .. }
                | ChangeEvent::UpdateName { name, .. }
                | ChangeEvent::DeleteName { name, .. }
                | ChangeEvent::NamedRangeAdjusted { name, .. } => Some(name.clone()),
                _ => None,
            })
            .collect()
    }

    fn prepare_name_dependent_span_demotion<'a>(
        &mut self,
        names: impl IntoIterator<Item = &'a str>,
    ) -> Result<Option<(PreparedFormulaSpanDemotion, Vec<CellRef>)>, crate::engine::EditorError>
    {
        if self.config.formula_plane_mode == FormulaPlaneMode::Off {
            return Ok(None);
        }
        let refs = self.exact_name_dependent_span_refs(names);
        if refs.is_empty() {
            return Ok(None);
        }

        // Exact demotion creates dirty legacy vertices. Preserve the old
        // span's clean/dirty state so the following name mutation remains the
        // sole authority that dirties formulas whose resolution changed.
        let dirty_coords = self.compute_current_formula_plane_dirty_result_coords()?;
        let clean_cells = {
            let authority = self.graph.formula_authority();
            refs.iter()
                .filter_map(|span_ref| authority.plane.spans.get(*span_ref))
                .flat_map(|span| span.domain.iter())
                .filter(|coord| !dirty_coords.contains(&(coord.sheet_id, coord.row, coord.col)))
                .map(|coord| {
                    CellRef::new(coord.sheet_id, Coord::new(coord.row, coord.col, true, true))
                })
                .collect::<Vec<_>>()
        };
        self.prepare_formula_span_demotion(&refs)
            .map(|prepared| Some((prepared, clean_cells)))
            .map_err(|error| match error {
                FormulaSpanDemotionError::Resource(error) => error.into(),
                error => crate::engine::EditorError::TransactionFailed {
                    reason: format!(
                        "FormulaPlane name-dependent demotion preparation failed: {error}"
                    ),
                },
            })
    }

    fn commit_name_dependent_span_demotion(
        &mut self,
        prepared: Option<(PreparedFormulaSpanDemotion, Vec<CellRef>)>,
    ) -> Result<bool, crate::engine::EditorError> {
        let Some((prepared, clean_cells)) = prepared else {
            return Ok(false);
        };
        self.commit_prepared_formula_span_demotion(prepared)
            .map_err(|error| crate::engine::EditorError::TransactionFailed {
                reason: format!("FormulaPlane name-dependent demotion commit failed: {error}"),
            })?;
        for cell in clean_cells {
            if let Some(&vertex_id) = self.graph.get_vertex_id_for_address(&cell) {
                self.graph.set_dirty(vertex_id, false);
            }
        }
        Ok(true)
    }

